import './App.css'
const nombre = 'FarmaPoint'
export default function App() { return <main><h1>{nombre}</h1><p>Productos de ejemplo: {2 + 3}</p></main> }

/* Estilos propios: estructura, estados de stock y diseño adaptable. */
.app {
  display:flex;
  min-height:100vh
}
aside {
  width:230px;
  background:#113d36;
  color:white;
  padding:34px 24px;
  position:fixed;
  height:100vh
}
.available {
  background:#e7f4e9;
  color:#227140
}
.sold {
  background:#fdebe6;
  color:#a34027
}
.product .warning {
  color:#9a6100
}
